class Solution {
public:
    int sumOfBeauties(vector<int>& nums) {
        int n = nums.size();
        int beauty = 0;

        int max_left = nums[0];
        for (int i = 1; i < n - 1; ++i) {
            if (max_left < nums[i]) {
                nums[i] = -nums[i];
                max_left = -nums[i];
            }
        }

        int min_right = nums[n - 1];
        for (int i = n - 2; i >= 1; --i) {
            if (nums[i] < 0 && -nums[i] < min_right) {
                beauty += 2;
            } else if (abs(nums[i - 1]) < abs(nums[i]) && abs(nums[i]) < abs(nums[i + 1])) {
                beauty += 1;
            }
            min_right = min(min_right, abs(nums[i]));
        }

        return beauty;
    }
};
